ValidationRule.errorConditionFormula:
AND( NOT($Setup.PMC_ProcessSwitches__c.PMC_BypassValidationRule__c), $Profile.Name <> 'System Administrator', $Profile.Name <> 'API Only profile', NOT(ISCHANGED( PMC_CPQ_FlowVRByPassToggle__c )), ISPICKVAL( PRIORVALUE(SBQQ__Status__c ), "Draft") , NOT( ISPICKVAL(SBQQ__Status__c, "Draft") ),
OR( ISPICKVAL(SBQQ__Status__c, "Presented"), ISPICKVAL( SBQQ__Status__c , "Accepted"), ISPICKVAL( SBQQ__Status__c , "Expired") ), NOT( ISNEW() )
)
